import os
import json
import requests

def extract_receipt_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("OPENAI_API_KEY")
    if not api_key:
        raise ValueError("Missing OpenAI API key")

    if isinstance(payload, (bytes, bytearray)):
        import base64
        payload = base64.b64encode(payload).decode("utf-8")

    if isinstance(payload, str) and payload.strip().startswith("http"):
        image_input = {"type": "input_image", "image_url": payload}
    else:
        image_input = {"type": "input_image", "image_url": f"data:image/jpeg;base64,{payload}"}

    response = requests.post(
        "https://api.openai.com/v1/responses",
        headers={
            "Authorization": f"Bearer {api_key}",
            "Content-Type": "application/json",
        },
        json={
            "model": config.get("model", "gpt-4.1-mini"),
            "input": [
                {
                    "role": "user",
                    "content": [
                        {
                            "type": "input_text",
                            "text": (
                                "Extract merchant, tax, total, and items from this receipt. "
                                "Return only valid JSON with keys: merchant (string), tax (number or null), "
                                "total (number or null), and items (array of objects with name, quantity, price)."
                            ),
                        },
                        image_input,
                    ],
                }
            ],
            "text": {"format": {"type": "json_object"}},
        },
        timeout=config.get("timeout", 60),
    )
    response.raise_for_status()
    data = response.json()

    text = ""
    for item in data.get("output", []):
        for content in item.get("content", []):
            if content.get("type") in ("output_text", "text"):
                text += content.get("text", "")

    result = json.loads(text) if text else {}
    return result
